    @Test void explicitDatedFieldsExportAllThirtySevenRows() throws Exception {
        exportPopulation37();JsonNode analysis=success("{}");String id=analysis.path("analysisId").asText();
        assertEquals(10,analysis.path("patients").path("items").size());assertEquals(37,analysis.path("n").asInt());
        MvcResult response=xlsx("{\"source\":\"COHORT\",\"analysisId\":\""+id+"\",\"fields\":[\"das28Current\",\"crpCurrent\"]}");
        assertEquals(200,response.getResponse().getStatus(),response.getResponse().getContentAsString());
        byte[] bytes=response.getResponse().getContentAsByteArray();assertTrue(bytes.length>1000);
        assertEquals("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",response.getResponse().getContentType());
        assertEquals("no-store",response.getResponse().getHeader("Cache-Control"));
        try(XSSFWorkbook book=new XSSFWorkbook(new ByteArrayInputStream(bytes))) {
            assertEquals(2,book.getNumberOfSheets());Sheet sheet=book.getSheet("cohort");assertEquals(37,sheet.getLastRowNum());assertEquals(2,sheet.getRow(0).getLastCellNum());
            for(int i=0;i<37;i++) {Cell das=sheet.getRow(i+1).getCell(0),crp=sheet.getRow(i+1).getCell(1);assertEquals(CellType.NUMERIC,das.getCellTypeEnum());assertEquals(CellType.NUMERIC,crp.getCellTypeEnum());assertEquals(BigDecimal.valueOf(37-i,1).doubleValue(),das.getNumericCellValue());assertEquals(10+i,crp.getNumericCellValue());}
            Sheet metadata=book.getSheet("metadata");assertNotNull(metadata);boolean rows=false;for(Row r:metadata)if("rowN".equals(r.getCell(0).getStringCellValue())){assertEquals(37,r.getCell(1).getNumericCellValue());rows=true;}assertTrue(rows);
        }
        String trace=response.getResponse().getHeader("X-Trace-Id");
        try(java.sql.Connection c=raw.getConnection();java.sql.PreparedStatement s=c.prepareStatement("SELECT generation_status,transfer_status,file_rows,file_bytes FROM ra_ai_export_audit WHERE id=?")) {s.setString(1,trace);try(java.sql.ResultSet r=s.executeQuery()){assertTrue(r.next());assertEquals("READY",r.getString(1));assertEquals("WRITTEN",r.getString(2));assertEquals(37,r.getInt(3));assertEquals(bytes.length,r.getInt(4));assertFalse(r.next());}}
        exited();
    }
