    @Test void datedComparisonExportsIndependentOracleAndNinePhysicalRows()throws Exception {
        fixedPatients();JsonNode inputs=json.readTree(getClass().getResourceAsStream("/ai-cohort/p04b/fixed-inputs.json"));assertEquals(14,inputs.path("mainPatients").size());JsonNode original=compareSuccess(filtersBody(true));String id=original.path("compareResultId").asText();resetOwners();context.getBean(CountingDictionary.class).calls=0;
        MvcResult r=xlsx("{\"source\":\"COMPARE\",\"compareResultId\":\""+id+"\",\"metrics\":[\"activity\",\"target\",\"haqAt\",\"crpAt\",\"das28At\",\"n\"]}");assertEquals(200,r.getResponse().getStatus(),r.getResponse().getContentAsString());JsonNode oracle=json.readTree(getClass().getResourceAsStream("/ai-cohort/p04b/independent-oracles.json")).path("mainComparison").path("afterExcludingIntersection");
        try(XSSFWorkbook book=new XSSFWorkbook(new ByteArrayInputStream(r.getResponse().getContentAsByteArray()))){Sheet sheet=book.getSheet("comparison");assertNotNull(sheet);assertEquals(9,sheet.getLastRowNum());java.util.Map<String,Integer> columns=columns(sheet);assertEquals(37,columns.size());assertEquals("n",sheet.getRow(1).getCell(0).getStringCellValue());numeric(sheet.getRow(1),columns,"aN","6");numeric(sheet.getRow(1),columns,"bN","6");
            String[][] names={{"das28At","das28"},{"crpAt","crp"},{"haqAt","haq"}};for(int n=0;n<3;n++){Row row=sheet.getRow(n+2);assertEquals(names[n][0],row.getCell(0).getStringCellValue());JsonNode expected=oracle.path("continuous").path(names[n][1]);for(String[] side:new String[][]{{"a","A"},{"b","B"}}){numeric(row,columns,side[0]+"ValidN","6");numeric(row,columns,side[0]+"UnknownN","0");for(String[] field:new String[][]{{"Q1","q1"},{"Median","median"},{"Q3","q3"},{"Iqr","iqr"}})numeric(row,columns,side[0]+field[0],expected.path(side[1]).path(field[1]).asText());}numeric(row,columns,"difference",expected.path("medianDifferenceAminusB").asText());xlsxTest(row,columns,expected.path("test"));}
            Row target=sheet.getRow(5);JsonNode e=oracle.path("binary").path("target");assertEquals("target",target.getCell(0).getStringCellValue());for(String[] side:new String[][]{{"a","A"},{"b","B"}}){numeric(target,columns,side[0]+"Numerator",e.path("display").path(side[1]).path("numerator").asText());numeric(target,columns,side[0]+"Denominator","6");numeric(target,columns,side[0]+"KnownN","6");numeric(target,columns,side[0]+"UnknownN","0");assertEquals(e.path("display").path(side[1]).path("rate").asDouble(),target.getCell(columns.get(side[0]+"Value")).getNumericCellValue(),1e-12);}assertEquals(e.path("display").path("differenceAminusBPercentagePoints").asDouble(),target.getCell(columns.get("difference")).getNumericCellValue(),1e-12);xlsxTest(target,columns,e.path("test"));
            JsonNode activity=oracle.path("activityDistribution");for(int k=0;k<4;k++){Row row=sheet.getRow(6+k);assertEquals(activity.path("categories").get(k).asText(),row.getCell(columns.get("category")).getStringCellValue());for(String[] side:new String[][]{{"a","A"},{"b","B"}}){numeric(row,columns,side[0]+"Count",activity.path(side[1]).path("counts").get(k).asText());numeric(row,columns,side[0]+"Denominator","6");numeric(row,columns,side[0]+"KnownN","6");numeric(row,columns,side[0]+"UnknownN","0");assertEquals(activity.path(side[1]).path("counts").get(k).asDouble()/6,row.getCell(columns.get(side[0]+"Value")).getNumericCellValue(),1e-12);}if(k==0)xlsxTest(row,columns,activity.path("test"));else for(String f:new String[]{"pValue","displayP","method","testStatus","reason","nA","nB","testDenominator","warnings"})assertEquals(CellType.BLANK,row.getCell(columns.get(f)).getCellTypeEnum());}
            assertEquals("9",metadata(book,"rowN"));assertEquals("6",metadata(book,"aN"));assertEquals("6",metadata(book,"bN"));assertEquals("6",metadata(book,"selectedItemsN"));
        }
        String trace=r.getResponse().getHeader("X-Trace-Id");try(java.sql.Connection c=raw.getConnection();java.sql.PreparedStatement q=c.prepareStatement("SELECT cohort_n,cohort_a_n,cohort_b_n,file_rows,generation_status,transfer_status FROM ra_ai_export_audit WHERE id=?")){q.setString(1,trace);try(java.sql.ResultSet a=q.executeQuery()){assertTrue(a.next());assertNull(a.getObject(1));assertEquals(6,a.getInt(2));assertEquals(6,a.getInt(3));assertEquals(9,a.getInt(4));assertEquals("READY",a.getString(5));assertEquals("WRITTEN",a.getString(6));}}
        assertEquals(0,context.getBean(CountingDictionary.class).calls);assertEquals(0,observed.displayReads);exited();
    }
    static java.util.Map<String,Integer> columns(Sheet sheet){java.util.Map<String,Integer> out=new java.util.LinkedHashMap<>();for(Cell c:sheet.getRow(0))out.put(c.getStringCellValue(),c.getColumnIndex());return out;}
    static void numeric(Row row,java.util.Map<String,Integer> cols,String field,String expected){Cell c=row.getCell(cols.get(field));assertEquals(CellType.NUMERIC,c.getCellTypeEnum(),field);assertEquals(0,new BigDecimal(expected).compareTo(new BigDecimal(((org.apache.poi.xssf.usermodel.XSSFCell)c).getRawValue())),field);}
    static void xlsxTest(Row row,java.util.Map<String,Integer> cols,JsonNode e){Cell p=row.getCell(cols.get("pValue"));assertEquals(CellType.NUMERIC,p.getCellTypeEnum());assertEquals(e.path("pValue").asDouble(),p.getNumericCellValue(),1e-12);for(String k:new String[]{"displayP","method"})assertEquals(e.path(k).asText(),row.getCell(cols.get(k)).getStringCellValue());assertEquals(e.path("status").asText(),row.getCell(cols.get("testStatus")).getStringCellValue());numeric(row,cols,"nA",e.path("nA").asText());numeric(row,cols,"nB",e.path("nB").asText());}
    static String metadata(XSSFWorkbook book,String key){for(Row r:book.getSheet("metadata"))if(key.equals(r.getCell(0).getStringCellValue())){Cell v=r.getCell(1);return v.getCellTypeEnum()==CellType.NUMERIC?((org.apache.poi.xssf.usermodel.XSSFCell)v).getRawValue():v.getStringCellValue();}throw new AssertionError("缺metadata "+key);}
