    @Test void completeInitialUniverseChangesOutsideSelectedCInvalidateBothSources()throws Exception {
        for(String source:new String[]{"COHORT","COMPARE"})for(String change:new String[]{"DELETE FROM patient_relation_doctor WHERE doctor_id=101 AND patient_id=137","DELETE FROM patient_basic_info WHERE id=137","INSERT INTO patient_basic_info(id,name) VALUES(138,'synthetic-new-U')"}){exportPopulation37();JsonNode d="COHORT".equals(source)?success("{\"filters\":{\"ids\":[\"101\"]}}"):compareSuccess("{\"a\":{\"source\":\"FILTERS\",\"filters\":{\"ids\":[\"101\"]}},\"b\":{\"source\":\"FILTERS\",\"filters\":{\"ids\":[\"102\"]}}}");boolean cohort="COHORT".equals(source);String id=d.path(cohort?"analysisId":"compareResultId").asText();byte[] original=cohort?analysisPayload(id):payload(id);sql(change);if(change.startsWith("INSERT"))sql("INSERT INTO patient_relation_doctor(doctor_id,patient_id,research_type) VALUES(101,138,0)");resetOwners();routeError("/api/ra/export/xlsx",("{\"source\":\""+source+"\",\""+(cohort?"analysisId":"compareResultId")+"\":\""+id+"\",\""+(cohort?"fields":"metrics")+"\":[\""+(cohort?"das28Current":"das28At")+"\"]}").getBytes("UTF-8"),409,"SCOPE_CHANGED");assertArrayEquals(original,cohort?analysisPayload(id):payload(id));assertEquals(0,count("ra_ai_export_audit"));assertEquals(0,context.getBean(ObservedWriter.class).completed);exited();}
    }
