    @Test void deeplyNestedSelectorsAreControlledBeforeAnySql()throws Exception {
        String digest=sourceDigest();for(String source:new String[]{"COHORT","COMPARE"})for(int depth:new int[]{4000,4500}){String ref="COHORT".equals(source)?"analysisId":"compareResultId",selector="COHORT".equals(source)?"fields":"metrics";String body="{\"source\":\""+source+"\",\""+ref+"\":\"00000000-0000-0000-0000-000000000001\",\""+selector+"\":"+String.join("",java.util.Collections.nCopies(depth,"["))+"0"+String.join("",java.util.Collections.nCopies(depth,"]"))+"}";int bytes=body.getBytes(java.nio.charset.StandardCharsets.UTF_8).length;assertTrue(bytes<16384);if("COHORT".equals(source))assertEquals(depth==4000?8082:9082,bytes);resetOwners();MvcResult r=assertDoesNotThrow(()->xlsx(body),"深结构须真实HTTP400，不能溢出请求线程");assertEquals(400,r.getResponse().getStatus());JsonNode e=json.readTree(r.getResponse().getContentAsByteArray());assertEquals("INVALID_REQUEST",e.path("code").asText());assertTrue(e.path("data").isNull());assertEquals(0,exportObserved.borrowed.get());assertEquals(0,count("ra_ai_export_audit"));assertEquals(0,context.getBean(ObservedWriter.class).completed);assertNull(r.getResponse().getHeader("Content-Disposition"));exited();}assertEquals(digest,sourceDigest());
    }
