        for(String setting:new String[]{"ra.export.xlsx.max-rows","ra.export.xlsx.max-cells"}){analysisProperties.put(setting,"10");context.close();buildContext(true);resetOwners();routeError("/api/ra/export/xlsx",body.getBytes("UTF-8"),413,"RESULT_TOO_LARGE");assertEquals(0,context.getBean(ObservedWriter.class).workbooksClosed);assertEquals(0,context.getBean(ObservedWriter.class).completed);analysisProperties.remove(setting);}
