        try(java.sql.Connection c=raw.getConnection();java.sql.PreparedStatement q=c.prepareStatement("SELECT payload_sha256 FROM ra_ai_export_audit WHERE id=?")){q.setString(1,exported.getResponse().getHeader("X-Trace-Id"));try(java.sql.ResultSet r=q.executeQuery()){assertTrue(r.next());assertEquals(writer.actualContentHash,r.getString(1));}}
